//! M20 (Mage: The Ascension 20th Anniversary Edition) - Compendium of Magical Practices
//!
//! Unabridged canonical reference text from Chapter 10 (Focus and Arts, pp. 573-586),
//! with full bilingual support (English & Portuguese), page numbers, associated paradigms,
//! abilities, common instruments, and the "Left- and Right-Hand Paths" sidebar box.

use serde::Serialize;
use crate::i18n::Language;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct CalloutBox {
    pub title: &'static str,
    pub title_pt: &'static str,
    pub page_ref: &'static str,
    pub content: &'static str,
    pub content_pt: &'static str,
}

impl CalloutBox {
    pub fn title(&self, lang: Language) -> &'static str {
        match lang {
            Language::PtBr => self.title_pt,
            Language::EnUs => self.title,
        }
    }

    pub fn content(&self, lang: Language) -> &'static str {
        match lang {
            Language::PtBr => self.content_pt,
            Language::EnUs => self.content,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct PracticeDefinition {
    pub id: &'static str,
    pub name: &'static str,
    pub name_pt: &'static str,
    pub aliases: &'static [&'static str],
    pub page_ref: &'static str,
    pub quote: &'static str,
    pub quote_pt: &'static str,
    pub paradigm_affinity: &'static [&'static str],
    pub paradigm_affinity_pt: &'static [&'static str],
    pub description: &'static str,
    pub description_pt: &'static str,
    pub common_instruments: &'static [&'static str],
    pub common_instruments_pt: &'static [&'static str],
    pub associated_abilities: &'static [&'static str],
    pub associated_abilities_pt: &'static [&'static str],
    pub callouts: &'static [CalloutBox],
}

impl PracticeDefinition {
    pub fn name(&self, lang: Language) -> &'static str {
        match lang {
            Language::PtBr => self.name_pt,
            Language::EnUs => self.name,
        }
    }

    pub fn quote(&self, lang: Language) -> &'static str {
        match lang {
            Language::PtBr => self.quote_pt,
            Language::EnUs => self.quote,
        }
    }

    pub fn description(&self, lang: Language) -> &'static str {
        match lang {
            Language::PtBr => self.description_pt,
            Language::EnUs => self.description,
        }
    }

    pub fn paradigm_affinity(&self, lang: Language) -> &'static [&'static str] {
        match lang {
            Language::PtBr => self.paradigm_affinity_pt,
            Language::EnUs => self.paradigm_affinity,
        }
    }

    pub fn common_instruments(&self, lang: Language) -> &'static [&'static str] {
        match lang {
            Language::PtBr => self.common_instruments_pt,
            Language::EnUs => self.common_instruments,
        }
    }

    pub fn associated_abilities(&self, lang: Language) -> &'static [&'static str] {
        match lang {
            Language::PtBr => self.associated_abilities_pt,
            Language::EnUs => self.associated_abilities,
        }
    }
}

pub const BOX_LEFT_AND_RIGHT_HAND_PATHS: CalloutBox = CalloutBox {
    title: "Left- and Right-Hand Paths",
    title_pt: "Caminhos da Mão Esquerda e da Mão Direita",
    page_ref: "M20, p. 574",
    content: "Originally named by Europeans trying to differentiate between separate approaches to Tantric practices, the terms Left-Hand Path and Right-Hand Path have come to reflect an outlaw approach to mysticism and a reverent approach to it, respectively. Supposedly, Left-Hand mystics favor sensuality, hedonism, intoxication, and other forms of disreputable bliss, whereas Right-Hand adherents prefer asceticism, reverence, denial, and other forms of disciplined devotion.\n\nIn truth, mystic practices (especially Tantra) are more complex than that simplified (and westernized) division between so-called bad and good behaviors. Even so, the distinction between Left- and Right-Hand approaches crops up a lot when people talk about crazy wisdom, witchcraft, chaos magick, and other practices that include socially questionable activities alongside socially approved ones.\n\nCertainly, some activities are more destructive than others, and magick does have consequences, like Resonance, that reach further than the moment of that act. Still, the division of Left- and Right-Hand magick tends to drop a Christianized gloss on practices that might be far older than Christianity and lack its simplistic bad/good moral polarity. Some modern mages employ that term as shorthand for their approach, but others avoid its easy answers to complicated questions.",
    content_pt: "Originalmente nomeados por europeus que tentavam diferenciar abordagens distintas nas práticas tântricas, os termos Caminho da Mão Esquerda e Caminho da Mão Direita passaram a refletir, respectivamente, uma abordagem fora-da-lei/marginalizada ao misticismo versus uma abordagem reverente e ortodoxa. Supostamente, os místicos da Mão Esquerda favoreceriam a sensualidade, o hedonismo, a intoxicação e outras formas de êxtase marginal, enquanto os adeptos da Mão Direita prefeririam o ascetismo, a reverência, a negação e outras formas de devoção disciplinada.\n\nNa verdade, as práticas místicas (especialmente o Tantra) são muito mais complexas do que essa divisão simplificada (e ocidentalizada) entre comportamentos supostamente 'maus' e 'bons'. Ainda assim, a distinção entre as abordagens da Mão Esquerda e da Direita surge com frequência quando as pessoas discutem sabedoria louca, bruxaria, magia do caos e outras práticas que misturam atividades socialmente questionáveis com outras socialmente aprovadas.\n\nCertamente, algumas atividades são mais destrutivas que outras, e a magia tem consequências — como a Ressonância — que vão muito além do momento do ato. Ainda assim, a divisão entre magia da Mão Esquerda e da Direita tende a impor um verniz cristão sobre práticas que podem ser muito mais antigas que o cristianismo e que não possuem essa polaridade moral simplista de bem contra o mal. Alguns magos modernos usam o termo como uma abreviação conveniente para sua abordagem, mas outros evitam essas respostas fáceis para questões complexas.",
};

